-- NIGHT1-MEA-SASIA-01: Dr. Bessie F. Lawrence International Summer Science Institute (ISSI)
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Dr. Bessie F. Lawrence International Summer Science Institute (ISSI)', 'dr bessie f lawrence international summer science institute issi', 'Weizmann Institute of Science (Davidson Institute for Science Education)', 'summer_program', 'https://www.weizmann.be/issi/', 'https://www.weizmann.be/issi/', 'A four-week English-language summer science program at the Weizmann Institute in Rehovot, Israel, for talented graduating high school students (and gap-year/early-undergraduate students) from around the world. Participants spend three weeks conducting hands-on research in Institute labs across biology, chemistry, physics, mathematics and computer science, then join a field-school excursion in the Judean Desert and Negev.', 'Israel', '{}', false, 18, 20, ARRAY['12'], ARRAY['biology','chemistry','physics','mathematics','computer_science'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, '{}', 'highly_selective', 'date_not_announced', 'Runs annually each summer; program is confirmed active via its Belgian ''Friends of Weizmann'' chapter page, but exact 2027 application deadline and calendar dates were not found on the pages accessible during this research pass.', 'official_primary', 'https://wis-wander.weizmann.ac.il/science-education/high-school-science-stars-17-countries-weizmann-institutes-summer-program', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-02: Ignite: International High School Summer Program
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Ignite: International High School Summer Program', 'ignite international high school summer program', 'Technion - Israel Institute of Technology', 'summer_program', 'https://int.technion.ac.il/programs/ignite-international-high-school-summer-program/', 'https://int.technion.ac.il/programs/ignite-international-high-school-summer-program/', 'A summer program on the Technion''s Haifa campus for international high school students with a strong science/engineering background who want to develop entrepreneurial and innovation skills. Combines academic enrichment with direct exposure to Israel''s research and startup ecosystem, plus a social/sightseeing program.', 'Israel', '{}', false, 17, NULL, '{}', ARRAY['engineering','computer_science','entrepreneurship','innovation'], NULL, NULL, '2026-04-29', NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['transcript','motivation_letter','recommendation_letter','passport_copy','test_scores_if_available'], 'selective', 'closed', '2026 cycle closed - application deadline was April 29, 2026 and the program ran in July 2026 (already concluded as of this research date); 2027 dates not yet announced.', 'official_primary', 'https://int.technion.ac.il/programs/ignite-international-high-school-summer-program/requirements-timelines/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-05: Chemical & Biological Engineering Boot Camp
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Chemical & Biological Engineering Boot Camp', 'chemical biological engineering boot camp', 'American University of Sharjah', 'summer_program', 'https://info.aus.edu/aus-events-0', 'https://forms.gle/XCC2MTW74TiKD3Ri6', 'A hands-on, three-day boot camp for high school students in AUS''s chemical and biological engineering laboratories, covering fundamentals of modern chemical and biological engineering practice. One of several short subject-specific boot camps AUS''s College of Engineering runs each June for Grades 10-12 students.', 'United Arab Emirates', '{}', false, NULL, NULL, ARRAY['10','11','12'], ARRAY['chemical_engineering','biological_engineering'], NULL, NULL, NULL, NULL, '2026-06-08', '2026-06-10', 'in_person', NULL, NULL, '{}', 'unknown', 'closed', '2026 edition completed June 8-10, 2026. AUS runs a similar slate of subject-specific boot camps (civil, mechanical, digital supply chain, plus a Sumo Robot Competition) each June; future dates not yet announced.', 'official_primary', 'https://info.aus.edu/aus-events-0', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-10: College Bound: AUC Pre-College Program
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('College Bound: AUC Pre-College Program', 'college bound auc precollege program', 'The American University in Cairo', 'summer_program', 'https://www.aucegypt.edu/academics/summeratauc/college-bound', 'https://www.aucegypt.edu/academics/summeratauc/college-bound', 'A three-week pre-college summer program at the American University in Cairo for students entering grades 10-12. Participants choose from AUC freshman-level courses (computer/data science, architecture, graphic design, business, entrepreneurship, political science, psychology, media studies, Arabic) taught by AUC faculty, with credit transferable if the student later enrolls at AUC.', 'Egypt', '{}', false, NULL, NULL, ARRAY['10','11','12'], ARRAY['computer_science','data_science','architecture','design','business','entrepreneurship','political_science','psychology','media_studies','arabic_language'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, '{}', 'unknown', 'closed', 'The Summer@AUC 2026 edition of College Bound has already concluded (''has come to an end. See you next summer in 2027!'' per the official page); 2027 dates/deadline not yet posted.', 'official_primary', 'https://www.aucegypt.edu/academics/summeratauc/college-bound', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-12: Young Scholars Programme (YSP)
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Young Scholars Programme (YSP)', 'young scholars programme ysp', 'Ashoka University', 'summer_program', 'https://www.ashoka.edu.in/ysp/', 'https://apply.ashoka.edu.in/eoiformysp.aspx', 'A certified, residential pre-college summer programme at Ashoka University (India) for students entering grades 9-12, offering interdisciplinary streams across the liberal arts and sciences: Foundations of Liberal Arts & Sciences, Frontiers of Science, and Tech/Data/Computer Science, among others including economics, psychology, policy and entrepreneurship.', 'India', '{}', false, NULL, NULL, ARRAY['9','10','11','12'], ARRAY['sciences','economics','finance','psychology','policy','international_affairs','business','entrepreneurship','data_science','computer_science','liberal_arts'], NULL, NULL, NULL, NULL, '2026-05-18', '2026-05-29', 'in_person', NULL, NULL, ARRAY['transcript','essay'], 'selective', 'closed', '2026 offered two editions - May 18-29, 2026 and June 1-12, 2026 - both already completed as of this research date; 2027 dates not yet announced.', 'official_primary', 'https://www.ashoka.edu.in/ysp/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-13: AUW Math and Science Summer School
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('AUW Math and Science Summer School', 'auw math and science summer school', 'Asian University for Women', 'summer_program', 'https://asian-university.org/academic-programs/summer-school/', 'https://forms.gle/wsUxUwbRVxL4wZma6', 'A four-week, Chevron-sponsored STEM summer school at the Asian University for Women''s Chattogram campus for female Bangladeshi high school students, covering mathematics, physics, chemistry, computer coding and public health, taught by international faculty from institutions including Oxford, MIT and the University of Dhaka. Top performers receive the AUW-Chevron Emerging Women Leader in STEM Award.', 'Bangladesh', ARRAY['Bangladesh'], false, NULL, NULL, '{}', ARRAY['mathematics','physics','chemistry','computer_science','public_health'], NULL, NULL, '2026-06-30', NULL, '2026-07-20', '2026-08-20', 'in_person', 'Female students who are residents of Bangladesh only, who have completed SSC/O-level or HSC/A-level.', 'Resident of Bangladesh.', ARRAY['academic_records'], 'highly_selective', 'closed', '2026 cohort''s program ran July 20-August 20, 2026 (concluded the day before this research date); application deadline for that cycle was June 30, 2026. 2027 cycle not yet announced.', 'official_primary', 'https://asian-university.org/academic-programs/summer-school/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-05: SAKURA Science High School Program
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('SAKURA Science High School Program', 'sakura science high school program', 'Japan Science and Technology Agency (JST)', 'academic_program', 'https://ssp.jst.go.jp/en/jst/highschool/', 'https://ssp.jst.go.jp/en/jst/highschool/', 'A flagship Japanese-government exchange initiative that invites high-achieving high school students (and an accompanying supervisor/teacher) from foreign countries, mainly across Asia, to Japan for a one-week program of lectures with leading scientists (including Nobel laureates), visits to top universities and research institutes such as JAXA and Hokkaido University, and collaborative activities with Japanese peers. Between 2014 and 2024, 67 courses were run for a total of 6,841 participating high school students.', 'Japan', '{}', false, NULL, NULL, '{}', ARRAY['science','stem','cultural exchange'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['nomination/submission via each country''s designated Sakura Science National Contact -- not a direct individual online application'], 'unknown', 'unverified', 'Ongoing annual JST invitation program with multiple weeklong course offerings per fiscal year; specific FY2026/FY2027 High School Program deadlines were not confirmed on the official pages fetched during this research pass', 'official_primary', 'https://ssp.jst.go.jp/en/jst/highschool/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-06: Taiwan International Science Fair (TISF)
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Taiwan International Science Fair (TISF)', 'taiwan international science fair tisf', 'National Taiwan Science Education Center (NTSEC)', 'competition', 'https://twsf.ntsec.gov.tw/activity/race-2/TISF2025/about-tisf.html', 'https://twsf.ntsec.gov.tw/activity/race-2/TISF2025/about-tisf.html', 'An annual (typically January) international pre-college science research fair held in Taipei, organized by the National Taiwan Science Education Center. Domestic and international students in grades 9-12 present original STEM research projects and compete for Young Scientist, First-to-Fourth, and Special Awards, in a format modeled on the Regeneron ISEF structure. The most recently fully-documented edition, TISF 2025 (20-25 January 2025), drew 629 domestic and overseas participants and 234 projects from 29 nations/regions.', 'Taiwan', '{}', false, NULL, NULL, ARRAY['9','10','11','12'], ARRAY['science','research','stem'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['selection/award at a qualifying national or regional-affiliate science fair in the student''s home country/region (e.g. an ISEF-affiliated fair) -- TISF is not normally directly self-applicable by an individual student without this qualifying step'], 'extremely_selective', 'date_not_announced', 'Held annually each January; most recently confirmed edition TISF 2025 (20-25 Jan 2025); a TISF 2026 edition page exists on the official site but its specific dates were not independently confirmed, and TISF 2027 dates were not found as of 2026-08-21', 'official_primary', 'https://twsf.ntsec.gov.tw/activity/race-2/TISF2025/about-tisf.html', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-08: HKU Summer Institute - Secondary School Programmes
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('HKU Summer Institute - Secondary School Programmes', 'hku summer institute secondary school programmes', 'The University of Hong Kong', 'summer_program', 'https://www.summerinstitute.hku.hk/programmes/secondary-school-programmes', 'https://www.summerinstitute.hku.hk/', 'The University of Hong Kong''s summer offering for secondary school students, spanning Research, Internship, Immersive, and Multi-location programme tracks across multiple grade bands (roughly S1-S6 / Year 8-13). Explicitly open to both local and non-local (international) students, with several multi-week sessions running through the northern-hemisphere summer.', 'Hong Kong', '{}', false, 15, NULL, '{}', ARRAY['multidisciplinary','research','stem','humanities'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, '{}', 'unknown', 'closed', '2026 cycle fully concluded -- the latest 2026 session ran through 3-7 August 2026; 2026 deadlines ranged from an early-bird 7 February 2026 discount through separate non-local/local deadlines in spring 2026; 2027 dates not yet posted', 'official_primary', 'https://www.summerinstitute.hku.hk/programmes/secondary-school-programmes', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-09: HKUST Pre-University Programs
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('HKUST Pre-University Programs', 'hkust preuniversity programs', 'Hong Kong University of Science and Technology (HKUST)', 'summer_program', 'https://join.hkust.edu.hk/pre-university', 'https://join.hkust.edu.hk/pre-university', 'A set of HKUST pre-university tracks for students in Year 11/Grade 10/Form 4 or above, distinct from HKUST''s separate nomination-only iElite Scholars Program. Tracks include the Summer Bootcamp for Polymath, credit-bearing Summer Institute courses (e.g. decision-making, chemistry, business risk, microbiology, Android development, human biology, sociology), Thematic-based Programs (entrepreneurship & innovation, discrete mathematics, STEM sensing, AI, smart learning design), a Collaborative Corporate Program with Tencent, and a Regional Program in Shanghai.', 'Hong Kong', '{}', false, NULL, NULL, ARRAY['10','11','12'], ARRAY['multidisciplinary','stem','entrepreneurship','business'], NULL, NULL, '2026-05-31', NULL, NULL, NULL, 'in_person', NULL, NULL, '{}', 'open_enrollment', 'closed', '2026 cycle fully concluded and closed to new registrants -- every listed 2026 track (running in the 19-31 July 2026 window) showed ''Full'' status by 2026-08-21; applications generally open Oct-Dec for a 31 May deadline the following year; 2027 cycle not yet open', 'official_primary', 'https://join.hkust.edu.hk/pre-university', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-10: The Hong Kong Award for Young People (AYP)
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('The Hong Kong Award for Young People (AYP)', 'the hong kong award for young people ayp', 'The Hong Kong Award for Young People', 'volunteering', 'https://ayp.org.hk/en/', 'https://camp.ayp.org.hk/', 'The Hong Kong operating authority for the global Duke of Edinburgh''s International Award, running non-formal education activities for young people across five sections (including an Adventurous Journey/expedition section), culminating in Bronze, Silver, and Gold awards. Delivered through schools, uniformed youth organisations, and community centres (over 600 ''operating units'' as of 2026) rather than a single central application. As of 2026, AYP reports 56,445 Bronze, 25,280 Silver, and 3,714 Gold award holders.', 'Hong Kong', ARRAY['Hong Kong'], false, 14, 24, '{}', ARRAY['leadership','volunteering','personal development','outdoor education'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['enrollment through a school, uniformed group, or community-centre Operating Unit'], 'open_enrollment', 'open', 'Rolling / continuous enrollment through Operating Units -- no fixed annual application deadline', 'official_primary', 'https://ayp.org.hk/en/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-05: Schulich Leader Scholarships
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Schulich Leader Scholarships', 'schulich leader scholarships', 'Schulich Leader Scholarships (Schulich Foundation)', 'scholarship', 'https://schulichleaders.com/', 'https://schulichleaders.com/', 'Canada''s largest STEM entrance scholarship program: 100 awards per year (50 at CAD $120,000 for engineering, 50 at CAD $100,000 for science/math/technology) for entrepreneurially minded, high-achieving Canadian graduating high school students entering a STEM undergraduate degree at one of 20 partner universities. Every Canadian secondary school may nominate one graduating student per year (Quebec CEGEPs may nominate up to four).', 'Canada', '{}', false, NULL, NULL, ARRAY['12'], ARRAY['science','technology','engineering','mathematics'], NULL, true, '2027-02-17', NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['school nomination (one student per high school; up to four per Quebec CEGEP)','online application','demonstrated academic excellence and leadership/entrepreneurial mindset'], 'extremely_selective', 'upcoming', '2027 entry cycle: nomination deadline Jan 27, 2027; student application deadline Feb 17, 2027; university decisions Mar 8-Jun 15, 2027', 'official_primary', 'https://schulichleaders.com/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-07: Loran Award
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Loran Award', 'loran award', 'Loran Scholars Foundation', 'scholarship', 'https://loranscholar.ca/', 'https://loranscholar.ca/the-program/how-to-apply/', 'A four-year, values-based undergraduate award (CAD $100,000 total: annual stipends, matching tuition waiver, and summer internship funding) for Canadian graduating high school or CEGEP students, selected primarily for character, service, and leadership potential rather than grades alone. Up to 36 Loran Scholars are named annually after a multi-stage selection process.', 'Canada', '{}', false, NULL, NULL, ARRAY['12'], '{}', NULL, true, NULL, NULL, NULL, NULL, 'in_person', 'Canadian citizenship or permanent resident status required', NULL, ARRAY['minimum 88% cumulative average (high school) or R-score >= 29 (CEGEP)','entering university for the first time in September 2027','born between Jan 1, 2005 and Sept 1, 2011 (high school applicants) or Sept 1, 2010 (CEGEP applicants)','multi-stage interviews (semi-final, then national finalist interviews in Toronto)'], 'extremely_selective', 'closed', 'Cycle for students entering university September 2027 — official site shows applications as closed as of research date 2026-08-21; specific closing date is not stated on the fetched page', 'official_primary', 'https://loranscholar.ca/the-program/how-to-apply/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-08: Forum for Young Canadians - National Summit
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Forum for Young Canadians - National Summit', 'forum for young canadians national summit', 'Rideau Hall Foundation', 'student_program', 'https://forum.ca/', 'https://forum.ca/apply/', 'A week-long, in-person civic-engagement program in Ottawa for Canadian youth ages 15-18, featuring simulations of Parliament and a national election, meetings with Members of Parliament and national decision-makers, and civic leadership skill-building. Operated by the Rideau Hall Foundation; the broader Forum initiative has run for 50 years with over 25,000 alumni.', 'Canada', '{}', false, 15, 18, '{}', ARRAY['civics','government','leadership','public policy'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, '{}', 'unknown', 'unverified', 'A 2026 National Summit cohort is referenced in current site content; exact 2027 cycle details could not be confirmed via direct official fetch as of research date', 'official_primary', 'https://forum.ca/about-forum/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-09: 2204-A High School Students Research Projects Competition
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('2204-A High School Students Research Projects Competition', '2204a high school students research projects competition', 'TUBITAK (The Scientific and Technological Research Council of Turkiye) - BIDEB', 'research', 'https://tubitak.gov.tr/en/competitions/2204-high-school-students-research-projects-competition', 'https://tybs.tubitak.gov.tr/', 'A long-running national research-project competition for high school students enrolled in Turkiye or the TRNC (57th edition as of the 2025-2026 cycle), run under teacher-advisor guidance with regional and national final rounds, spanning fundamental, social, and applied science topics.', 'Turkey', '{}', false, NULL, NULL, ARRAY['9','10','11','12'], ARRAY['science','social science','engineering','research methods'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, 'Must be enrolled as a high school student in Turkiye or the Turkish Republic of Northern Cyprus (TRNC)', ARRAY['online application via TUBITAK''s Management Information System (tybs.tubitak.gov.tr)','teacher/advisor guidance','written project report following the official project-writing guide'], 'competitive_award', 'date_not_announced', '57th edition (2025-2026 cycle, application deadline was Dec 12, 2025) has concluded. The next cycle (58th, 2026-2027) was not listed among TUBITAK BIDEB''s currently open-for-application programs as of Aug 21, 2026 (checked directly against ebideb.tubitak.gov.tr/basvuruacikprogramlar.htm) — not yet announced.', 'official_primary', 'https://tubitak.gov.tr/en/competitions/2204-high-school-students-research-projects-competition', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-10: Ulusal Bilim Olimpiyatlari (National Science Olympiads) - TUBITAK 2202
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Ulusal Bilim Olimpiyatlari (National Science Olympiads) - TUBITAK 2202', 'ulusal bilim olimpiyatlari national science olympiads tubitak 2202', 'TUBITAK (The Scientific and Technological Research Council of Turkiye) - BIDEB', 'competition', 'https://bilimolimpiyatlari.tubitak.gov.tr/tr/ulusal-bilim-olimpiyatlari', 'https://ebideb.tubitak.gov.tr/basvuruacikprogramlar.htm', 'Turkiye''s national multi-stage science olympiad program across nine subject areas (Astronomy-Astrophysics, Geography, Mathematics, Physics, Chemistry, Biology, Computer Science, plus middle-school Mathematics/Computer Science tracks), used to select Turkiye''s national teams for International Science Olympiads. The pipeline runs through a first-stage exam, summer school, second-stage exam, winter school, and team-selection camps.', 'Turkey', '{}', false, NULL, NULL, ARRAY['8','9','10','11'], ARRAY['mathematics','physics','chemistry','biology','computer science','astronomy','geography'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, 'Enrolled students in grades 8, preparatory, 9, 10, or 11 depending on subject (varies by field); final-year high school students are not eligible to apply', ARRAY['registration via ebideb.tubitak.gov.tr','First Stage Exam (multiple choice, held at 81 provincial centers plus TRNC)'], 'extremely_selective', 'date_not_announced', 'Not among TUBITAK BIDEB''s currently open-for-application programs as of Aug 21, 2026 (checked directly against ebideb.tubitak.gov.tr/basvuruacikprogramlar.htm); exact next-cycle dates not yet announced', 'official_primary', 'https://bilimolimpiyatlari.tubitak.gov.tr/tr/ulusal-bilim-olimpiyatlari', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-11: GencBizz Lise Girisimcilik Programi (High School Entrepreneurship Program)
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('GencBizz Lise Girisimcilik Programi (High School Entrepreneurship Program)', 'gencbizz lise girisimcilik programi high school entrepreneurship program', 'Genc Basari Egitim Vakfi (Junior Achievement Turkey)', 'entrepreneurship', 'https://gencbasari.org/lise', 'https://gencbasari.org/gencbizz/', 'A national experiential-entrepreneurship program in which teams of 13-18-year-old high school students (5-10 per team) launch and run a real zero-capital student company for a school year under business-volunteer mentorship and teacher guidance, then liquidate it at year end. Delivered under a protocol with Turkiye''s Ministry of National Education across all 81 provinces, as part of the global Junior Achievement network.', 'Turkey', '{}', false, 13, 18, ARRAY['9','10','11','12'], ARRAY['entrepreneurship','business'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['participating school/teacher enrollment','team formation (5-10 students)'], 'open_enrollment', 'date_not_announced', 'Runs on the Turkish school-year calendar (e.g. the 2025-2026 cycle''s implementation phase was announced around October 2025 per secondary press coverage); the 2026-2027 cycle''s announcement was not located on the official site as of this research', 'official_primary', 'https://gencbasari.org/lise', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-12: Izmir Ekonomi Universitesi Lise Yaz Okulu (High School Summer School)
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Izmir Ekonomi Universitesi Lise Yaz Okulu (High School Summer School)', 'izmir ekonomi universitesi lise yaz okulu high school summer school', 'Izmir University of Economics', 'summer_program', 'https://ekosem.ieu.edu.tr/tr/izmir-ekonomi-universitesi-lise-yaz-okulu', 'https://ekosem.ieu.edu.tr/tr/izmir-ekonomi-universitesi-lise-yaz-okulu', 'A campus-based summer program at Izmir University of Economics'' Balcova campus for high school students planning to apply to universities in Europe or the US, offering English-language tracks (verified 2023 edition: Artificial Organ Technologies, Sustainable Economy, Sustainable Finance) and a completion certificate intended to strengthen international university applications.', 'Turkey', '{}', false, NULL, NULL, '{}', ARRAY['engineering','economics','finance'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, '{}', 'unknown', 'unverified', 'The officially fetched page describes the 2023 edition (Aug 14-25, 2023; ~45 students accepted; application deadline Aug 1, 2023). Secondary, search-only (not independently WebFetched) signals suggest the program continues annually in early-to-mid August with a similar structure, but current-cycle (2026) exact dates could not be confirmed via direct official fetch.', 'official_primary', 'https://www.ieu.edu.tr/tr/news/type/read/id/8623', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-15: CTYI Summer Programme
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('CTYI Summer Programme', 'ctyi summer programme', 'Centre for Talented Youth, Ireland (CTYI), Dublin City University', 'summer_program', 'https://www.dcu.ie/ctyi/ctyi-summer-programme-centre-talented-youth-ireland', 'https://www.dcu.ie/ctyi', 'A fast-paced, university-style academic enrichment program at Dublin City University for academically talented students aged 12-16 (95th-percentile ability), run as two separate three-week sessions each June and July, with both residential and commuter options.', 'Ireland', '{}', false, 12, 16, '{}', '{}', NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['Post-Primary Talent Search assessment OR an Educational Psychologist''s report demonstrating 95th-percentile academic ability'], 'highly_selective', 'closed', 'A secondary (search-indexed) reference to dcu.ie indicated Summer 2026 applications had already closed as of this research; exact 2027 dates are not yet posted on the pages directly fetched', 'official_primary', 'https://www.dcu.ie/ctyi/centre-talented-youth-ireland-secondary-school-programme-overview', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-17: Jugend forscht
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Jugend forscht', 'jugend forscht', 'Stiftung Jugend forscht e.V.', 'competition', 'https://www.jugend-forscht.de/', 'https://www.jugend-forscht.de/teilnahme/wichtige-infos/teilnahmebedingungen.html', 'Germany''s best-known youth research competition: students from grade 4 up to age 21 submit self-chosen research projects across seven MINT fields (working world, biology, chemistry, geo/space science, mathematics/computer science, physics, technology), progressing through regional, state (Landeswettbewerb), and federal (Bundeswettbewerb) rounds. Entrants 15 and older compete in the main ''Jugend forscht'' category; younger entrants compete in ''Jugend forscht junior''.', 'Germany', '{}', false, NULL, 21, '{}', ARRAY['mathematics','computer science','physics','chemistry','biology','geoscience','technology'], NULL, true, '2026-11-30', NULL, '2027-01-17', '2027-05-30', 'in_person', NULL, NULL, ARRAY['online registration','written project report (due mid-January)','individual entry or team of 2-3'], 'competitive_award', 'upcoming', '62nd competition round (2027): registration deadline Nov 30, 2026; written submissions due Jan 17, 2027; state rounds Apr 7-9, 2027 in Stuttgart; federal final (Bundesfinale) May 27-30, 2027 in Wurzburg', 'official_primary', 'https://www.jugend-forscht.de/teilnahme/wichtige-infos/teilnahmebedingungen.html', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-SELF-02: Hack Club
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Hack Club', 'hack club', 'Hack Club (501(c)(3) nonprofit)', 'student_program', 'https://hackclub.com/', 'https://hackclub.com/', 'Global nonprofit membership community for teenage makers: 1,500+ in-person high-school clubs worldwide plus an online community, running a rotating slate of free build challenges/events, and financial and technical tools for teen-led tech projects. Not a single event -- an ongoing community students can join at any time.', NULL, '{}', true, 13, 18, '{}', ARRAY['computer science','technology','maker / DIY'], 0, NULL, NULL, NULL, NULL, NULL, 'hybrid', NULL, NULL, ARRAY['join online community or start/join a local club'], 'open_enrollment', 'open', 'Ongoing membership community, not cycle-bound -- join at any time.', 'official_primary', 'https://hackclub.com/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-SELF-04: Jane Goodall's Roots & Shoots (USA)
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Jane Goodall''s Roots & Shoots (USA)', 'jane goodalls roots shoots usa', 'Jane Goodall Institute', 'volunteering', 'https://rootsandshoots.org/', 'https://rootsandshoots.org/', 'Free youth environmental and humanitarian action movement founded by Jane Goodall. Members (individuals, classrooms, or community groups) design and run their own community-led service projects using a ''4-Step Formula'' (Get Inspired, Observe, Take Action, Celebrate). US chapter reports 2,118 registered groups across all 50 states; sister chapters exist in Canada, the UK, and globally (see research_notes) but were not independently verified this pass.', 'United States', '{}', true, NULL, NULL, '{}', ARRAY['environment','community service','humanitarian action'], 0, NULL, NULL, NULL, NULL, NULL, 'hybrid', NULL, NULL, ARRAY['online registration as an individual or group'], 'open_enrollment', 'open', 'Ongoing movement, not cycle-bound -- register and start a project at any time.', 'official_primary', 'https://rootsandshoots.org/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-SELF-05: Congress-Bundestag Youth Exchange (CBYX) for High School Students
INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Congress-Bundestag Youth Exchange (CBYX) for High School Students', 'congressbundestag youth exchange cbyx for high school students', 'U.S. Department of State, in partnership with the German Bundestag', 'fellowship', 'https://exchanges.state.gov/us/program/congress-bundestag-youth-exchange-high-school-students', 'http://www.usagermanyscholarship.org/app/', 'Government-sponsored merit-based youth exchange sending U.S. high school students to Germany for a full academic year of study and cultural immersion, administered by the U.S. Department of State together with the German Bundestag. No prior German language skills required.', 'United States', '{}', false, 15, 18, '{}', ARRAY['cultural exchange','German language and culture'], NULL, NULL, NULL, NULL, NULL, NULL, 'in_person', 'U.S. citizens only, per the official page fetched.', NULL, ARRAY['GPA 2.5+ (4.0 scale)','apply via usagermanyscholarship.org'], 'selective', 'unverified', 'A search result (not independently page-verified this pass) referenced a 2026-27 CBYX High School Application page at usagermanyscholarship.org -- not confirmed directly; check that site for exact current deadlines before displaying one to students.', 'official_primary', 'https://exchanges.state.gov/us/program/congress-bundestag-youth-exchange-high-school-students', 'high', 'active', 'verified_current', '2026-08-21');

