-- NIGHT1-MEA-SASIA-03: NYU Abu Dhabi Summer Academy -- cost='Free - covered by the Sheikh Mohamed bin Zayed Scholarship for Outstanding High School Students'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('NYU Abu Dhabi Summer Academy', 'nyu abu dhabi summer academy', 'New York University Abu Dhabi', 'summer_program', 'https://nyuad.nyu.edu/en/academics/community-programs/summer-academy.html', 'https://nyuad.nyu.edu/en/academics/community-programs/summer-academy/application-and-selection-process.html', 'An 18-month university-preparation program for Emirati high school students, built around two intensive summer sessions on NYU Abu Dhabi''s Saadiyat Island campus plus online study and academic refresher weekends during the school year. Covers mathematics, critical thinking and writing, humanities, and leadership/public-speaking skills, fully funded by a named scholarship.', 'United Arab Emirates', ARRAY['United Arab Emirates'], false, NULL, NULL, ARRAY['10'], ARRAY['mathematics','writing','humanities','leadership'], 'Free - covered by the Sheikh Mohamed bin Zayed Scholarship for Outstanding High School Students', true, '2026-01-16', NULL, '2026-07-06', '2026-08-07', 'in_person', 'Emirati nationals only - applicant must hold an Emirati passport or be the child of an Emirati mother.', 'Must be enrolled in a UAE high school, in Grade 10 (or equivalent) at time of nomination.', ARRAY['nomination','application','interview','diagnostic_assessment'], 'highly_selective', 'closed', '2026 cohort''s summer session just concluded (ran July 6-August 7, 2026); this is an 18-month program so the 2026-intake cohort continues into 2027 academic-year components. Next new-cohort nomination cycle not yet announced.', 'official_primary', 'https://nyuad.nyu.edu/en/academics/community-programs/summer-academy/application-and-selection-process.html', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-04: NYU Abu Dhabi University Prep Program (UPP) -- cost='Free - program materials and meals included; travel and accommodation are not covered'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('NYU Abu Dhabi University Prep Program (UPP)', 'nyu abu dhabi university prep program upp', 'New York University Abu Dhabi', 'student_program', 'https://nyuad.nyu.edu/en/apply/undergraduate/connect-with-us/university-prep-program.html', 'https://connect.nyu.edu/register/?id=0cb6d1f8-0ff8-4d32-a962-64e4eaf7b772', 'A free two-day, in-person, on-campus workshop at NYU Abu Dhabi that helps rising high school seniors of any nationality build a stronger Common Application, through goal-reflection exercises, application-skills workshops, and peer community-building. Open globally to students planning to apply for the relevant admissions cycle, not restricted to UAE nationals or residents.', 'United Arab Emirates', '{}', false, NULL, NULL, ARRAY['11','12'], '{}', 'Free - program materials and meals included; travel and accommodation are not covered', NULL, '2026-05-25', NULL, '2026-07-04', '2026-07-05', 'in_person', NULL, NULL, ARRAY['transcript','recommendation_letter_optional'], 'selective', 'closed', '2026 edition completed July 4-5, 2026 (application deadline May 25, 2026, has passed); 2027 dates not yet announced.', 'official_primary', 'https://nyuad.nyu.edu/en/apply/undergraduate/connect-with-us/university-prep-program.html', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-06: KAUST High School Summer Program (HSSP) -- cost='SAR 35,000 (Oxford track) or SAR 40,000 (Cambridge track), plus a SAR 200 non-refundable application fee; covers flights, accommodation, meals, tuition, materials, activities and mentorship.'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('KAUST High School Summer Program (HSSP)', 'kaust high school summer program hssp', 'King Abdullah University of Science and Technology (KAUST)', 'summer_program', 'https://academy.kaust.edu.sa/program/pre-university/high-school-summer-program-hssp-2026/', 'https://academy.kaust.edu.sa/program/pre-university/high-school-summer-program-hssp-2026/', 'A highly selective international STEM program for high-achieving high school students, combining intensive on-campus learning at KAUST (Saudi Arabia) with a residential academic track at either Oxford University or the University of Cambridge. Covers mathematics, programming, physics, chemistry, biology, AI, engineering and data science.', 'Saudi Arabia', '{}', false, 16, NULL, '{}', ARRAY['mathematics','computer_science','physics','chemistry','biology','artificial_intelligence','engineering','data_science'], 'SAR 35,000 (Oxford track) or SAR 40,000 (Cambridge track), plus a SAR 200 non-refundable application fee; covers flights, accommodation, meals, tuition, materials, activities and mentorship.', NULL, '2026-05-14', NULL, '2026-07-10', '2026-08-22', 'in_person', NULL, NULL, ARRAY['application','interview'], 'highly_selective', 'closed', '2026 cohort: applications closed May 14, 2026; Oxford track ran July 10-August 1, 2026, Cambridge track runs August 1-22, 2026 (concluding within days of this research date). 2027 cycle not yet announced.', 'official_primary', 'https://academy.kaust.edu.sa/program/pre-university/high-school-summer-program-hssp-2026/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-07: Saudi Research Science Institute (SRSI) -- cost='SAR 200 non-refundable application fee; program tuition/cost itself not disclosed on the page accessed'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Saudi Research Science Institute (SRSI)', 'saudi research science institute srsi', 'King Abdullah University of Science and Technology (KAUST)', 'summer_program', 'https://academy.kaust.edu.sa/program/pre-university/srsi/', 'https://academy.kaust.edu.sa/program/pre-university/srsi/', 'A six-week program at KAUST blending advanced STEM coursework with supervised laboratory research - described as the first program of its kind in Saudi Arabia. Restricted to Saudi national students in Grade 11.', 'Saudi Arabia', ARRAY['Saudi Arabia'], false, NULL, NULL, ARRAY['11'], ARRAY['stem','laboratory_research'], 'SAR 200 non-refundable application fee; program tuition/cost itself not disclosed on the page accessed', NULL, '2026-01-15', NULL, NULL, NULL, 'in_person', 'Saudi National students only.', NULL, ARRAY['transcript','application','recommendation_letter','interview'], 'highly_selective', 'closed', '2026 application cycle closed January 15, 2026 (hard cutoff January 22 for fee/document completion); 6-week program held over the 2026 summer. 2027 cycle not yet announced.', 'official_primary', 'https://academy.kaust.edu.sa/program/pre-university/srsi/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-08: STEPs (KAUST Academy College Preparation Program) -- cost='Free - fully funded including accommodation and meals; SAR 200 non-refundable application fee'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('STEPs (KAUST Academy College Preparation Program)', 'steps kaust academy college preparation program', 'King Abdullah University of Science and Technology (KAUST)', 'academic_program', 'https://academy.kaust.edu.sa/program/college-preparation-programs/steps-kaust/', 'https://academy.kaust.edu.sa/program/college-preparation-programs/steps-kaust/', 'A 10-month, fully-funded college-preparation pathway for Saudi Grade 10 students, combining online components, a summer program, and a fall program, designed to prepare participants for admission to top global universities.', 'Saudi Arabia', ARRAY['Saudi Arabia'], false, NULL, NULL, ARRAY['10'], ARRAY['stem','mathematics','science'], 'Free - fully funded including accommodation and meals; SAR 200 non-refundable application fee', true, '2026-03-26', NULL, NULL, NULL, 'in_person', 'Saudi students only.', NULL, ARRAY['transcript','admissions_test','interview'], 'highly_selective', 'closed', '2025-26 cohort: registration closed March 26, 2026, admissions test March 31, results late April; online phase April-June 2026, summer phase July-August 2026, fall phase November 2026 (program in progress as of this research date). Next admissions cycle not yet announced.', 'official_primary', 'https://academy.kaust.edu.sa/program/college-preparation-programs/steps-kaust/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-09: SPAAC Summer Program -- cost="Not finalized at time of research ('TBD' on the official page for all four track/accommodation combinations); fee is stated to include tuition, medical insurance, gym access, meals and activities/trips."
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('SPAAC Summer Program', 'spaac summer program', 'American University of Beirut', 'summer_program', 'https://www.aub.edu.lb/cec/Pages/SPAAC.aspx', 'https://www.aub.edu.lb/cec/Pages/SPAAC.aspx', 'A one- to two-week campus-residential program at the American University of Beirut for students aged 14-18 from around the world, run by AUB''s Continuing Education Center with its alumni association. Combines Arabic language and Lebanese-culture instruction with electives such as design, acting, game development, mobile app development and engineering exploration, plus supervised excursions to historical sites across Lebanon.', 'Lebanon', '{}', false, 14, 18, '{}', ARRAY['arabic_language','middle_eastern_studies','design','arts','engineering'], 'Not finalized at time of research (''TBD'' on the official page for all four track/accommodation combinations); fee is stated to include tuition, medical insurance, gym access, meals and activities/trips.', NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, '{}', 'unknown', 'date_not_announced', 'AUB''s broader family of pre-university summer programs (including SPAAC) run in July each year, per the general Summer@AUB page for 2026; the SPAAC-specific page did not list exact 2026 dates or pricing at the time of this research pass.', 'official_primary', 'https://www.aub.edu.lb/Summer@AUB/Pages/default.aspx', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-11: Georgetown Pre-College Summer (GPS) Program -- cost='QAR 3,700 (with SAT-prep track) or QAR 1,850 (without SAT-prep track)'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Georgetown Pre-College Summer (GPS) Program', 'georgetown precollege summer gps program', 'Georgetown University in Qatar', 'summer_program', 'https://guq.qatar.georgetown.edu/academics/programs-high-school-students/georgetown-pre-college-summer-program-gps/', 'https://guq.qatar.georgetown.edu/academics/programs-high-school-students/georgetown-pre-college-summer-program-gps/', 'A three-week full-time summer program at Georgetown University in Qatar giving local students a head start on the university application process - International Relations coursework taught by Georgetown graduates, with an optional SAT-preparation track taught by Princeton Review-certified instructors, plus co-curricular sessions led by current Georgetown students.', 'Qatar', ARRAY['Qatar'], false, NULL, NULL, ARRAY['11','12'], ARRAY['international_relations','test_prep'], 'QAR 3,700 (with SAT-prep track) or QAR 1,850 (without SAT-prep track)', NULL, '2026-04-30', NULL, '2026-07-04', '2026-07-23', 'in_person', 'Program explicitly targets ''local students in Qatar''; preference criteria require applicants to be a Qatar national or resident.', 'Must be a Qatar resident (or national); entering the final two years of secondary school.', ARRAY['transcript'], 'selective', 'closed', '2026 cycle closed - program ran July 4-23, 2026 with an application deadline of April 30, 2026 (both already passed as of this research date); 2027 dates not yet announced.', 'official_primary', 'https://guq.qatar.georgetown.edu/academics/programs-high-school-students/georgetown-pre-college-summer-program-gps/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-14: UAE Hackathon - Rising Stars Track -- cost='Free (no participation fee found)'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('UAE Hackathon - Rising Stars Track', 'uae hackathon rising stars track', 'UAE Hackathon', 'hackathon', 'https://hackathon.ae/', 'https://hackathon.ae/', 'The school-students track of the UAE Hackathon, a national innovation initiative now in its ninth edition. Teams of 2-7 students aged 11-17 build prototypes addressing national-challenge themes, competing through regional hackathon events toward a national Innovation Summit and Awards Ceremony.', 'United Arab Emirates', ARRAY['United Arab Emirates'], false, 11, 17, '{}', ARRAY['technology','innovation','entrepreneurship'], 'Free (no participation fee found)', NULL, NULL, NULL, '2026-10-19', '2026-11-11', 'in_person', NULL, 'Participation is explicitly limited to participants residing within the UAE with a valid Emirates ID - not open to non-UAE-resident international applicants.', ARRAY['team_registration'], 'competitive_award', 'upcoming', '2026 edition is upcoming as of this research date: regional hackathons run October 19-29, 2026, with the Innovation Summit and Awards Ceremony on November 11, 2026 (the official FAQ page also references post-hackathon support continuing November 16-27, 2026).', 'official_primary', 'https://hackathon.ae/en/FAQs', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-15: SparkTank -- cost='Free (zero incubation fee)'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('SparkTank', 'sparktank', 'Beaconhouse', 'entrepreneurship', 'https://sparktankincubator.com/', 'https://sparktankincubator.com/enrol-for-incubation/', 'Pakistan''s first business incubator/competition for students aged 10-19, open to students at any public or private school across Pakistan regardless of school affiliation. Selected teams (individuals or groups of up to 4) receive a zero-fee incubation period to develop a business concept, judged on viability and potential for positive social impact.', 'Pakistan', ARRAY['Pakistan'], false, 10, 19, '{}', ARRAY['entrepreneurship','business'], 'Free (zero incubation fee)', true, NULL, NULL, NULL, NULL, 'in_person', NULL, 'Must attend a school (public or private) in Pakistan.', ARRAY['proposal'], 'selective', 'date_not_announced', 'Runs two cohorts per year on a rolling basis; specific 2026/2027 cohort application windows were not published on the pages accessed during this research pass (program materials show some internal inconsistency between a stated ''5-month'' and a ''3-month plus extension'' incubation length).', 'official_primary', 'https://sparktankincubator.com/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-MEA-SASIA-16: ROTA Programme -- cost='Free (unpaid volunteering)'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('ROTA Programme', 'rota programme', 'Education Above All Foundation', 'volunteering', 'https://www.educationaboveall.org/support-eaa/volunteer', 'https://www.educationaboveall.org/support-eaa/volunteer', 'An ongoing youth-and-young-adult volunteering programme run by Qatar''s Education Above All Foundation, supporting EAA events, partner-led events, and longer-term volunteer commitments tied to the Foundation''s national and international education initiatives.', 'Qatar', '{}', false, 15, 35, '{}', ARRAY['community_service','education'], 'Free (unpaid volunteering)', NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['application_form'], 'open_enrollment', 'open', 'Rolling/ongoing volunteer registration with no fixed application cycle or deadline.', 'official_primary', 'https://www.educationaboveall.org/support-eaa/volunteer', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-01: Professor Harry Messel International Science School (ISS) -- cost='Free - fully funded by ISS scholarships (travel, accommodation, meals, and activities covered)'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Professor Harry Messel International Science School (ISS)', 'professor harry messel international science school iss', 'University of Sydney', 'summer_program', 'https://www.sydney.edu.au/science/industry-and-community/community-engagement/international-science-school.html', 'https://www.sydney.edu.au/science/industry-and-community/community-engagement/international-science-school.html', 'A fully-funded, two-week residential science program held at the University of Sydney every two years for high-achieving Year 11/12 science students. Around 110 scholars attend each edition -- roughly two-thirds from Australia and one-third nominated from eight partner countries. Students attend lectures by leading scientists, tour research laboratories, and take part in interactive demonstrations. All costs (travel, accommodation, meals, activities) are covered by ISS scholarships funded by the Physics Foundation at the University of Sydney.', 'Australia', ARRAY['Australia','China','India','Japan','New Zealand','Thailand','Singapore','United Kingdom','United States'], false, NULL, NULL, ARRAY['11','12'], ARRAY['science','stem'], 'Free - fully funded by ISS scholarships (travel, accommodation, meals, and activities covered)', true, NULL, NULL, NULL, NULL, 'in_person', 'Australian applicants must be citizens or permanent residents attending school in Australia. International places are by nomination from eight named partner countries only (China, India, Japan, New Zealand, Thailand, Singapore, UK, USA) -- not a general open-international application.', NULL, ARRAY['personal statement (500 words)','school recommendation','academic transcript/grades'], 'highly_selective', 'upcoming', 'Biennial -- most recently held 6-19 July 2025; next edition expected mid-2027 with applications opening early 2027 (exact dates not yet published as of 2026-08-21)', 'official_primary', 'https://www.sydney.edu.au/science/industry-and-community/community-engagement/international-science-school.html', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-02: National Youth Science Forum (NYSF) - Year 12 Program -- cost='AUD 3,180 program fee (due October 2026) plus a AUD 70 non-refundable application fee; Access and Equity Scholarships available for students facing financial hardship'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('National Youth Science Forum (NYSF) - Year 12 Program', 'national youth science forum nysf year 12 program', 'National Youth Science Forum', 'summer_program', 'https://www.nysf.edu.au/what-we-do/how-to-apply/', 'https://www.nysf.edu.au/what-we-do/how-to-apply/', 'A residential STEM enrichment program for students about to enter Year 12, held every January in Canberra and Brisbane. Participants attend lectures, labs, and site visits with STEM professionals and researchers, and explore university/career pathways in science, technology, engineering and mathematics. Formerly known as the National Science Summer School (until 1995).', 'Australia', ARRAY['Australia'], false, NULL, NULL, ARRAY['11'], ARRAY['science','technology','engineering','mathematics','stem'], 'AUD 3,180 program fee (due October 2026) plus a AUD 70 non-refundable application fee; Access and Equity Scholarships available for students facing financial hardship', true, '2026-07-23', NULL, '2027-01-06', '2027-01-14', 'in_person', 'Must be an Australian citizen or permanent resident, and/or studying full-time at an Australian high school. International students are not eligible for the standard application pathway but are invited to email nysf@nysf.edu.au to express interest in alternative participation.', NULL, ARRAY['most recent school report','statement of STEM areas of interest','session preference'], 'selective', 'closed', '2027 program: applications closed 23 July 2026, with outcomes advised mid-August 2026; two 2027 sessions run in Canberra (6-14 Jan) and Brisbane (13-21 Jan)', 'official_primary', 'https://www.nysf.edu.au/what-we-do/how-to-apply/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-03: The Duke of Edinburgh's International Award - Australia -- cost='Varies by school/operating Centre; not centrally published on the national site'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('The Duke of Edinburgh''s International Award - Australia', 'the duke of edinburghs international award australia', 'The Duke of Edinburgh''s International Award - Australia', 'volunteering', 'https://dukeofed.com.au/', 'https://dukeofed.com.au/', 'The Australian operating arm of the global Duke of Edinburgh''s International Award, a non-formal education framework built around Voluntary Service, Physical Recreation, Skills, and an Adventurous Journey, culminating in Bronze, Silver, and Gold Award levels. Delivered through schools, community organisations, and accredited Duke of Ed Centres rather than a single central application.', 'Australia', ARRAY['Australia'], false, 14, 24, '{}', ARRAY['leadership','volunteering','personal development'], 'Varies by school/operating Centre; not centrally published on the national site', NULL, NULL, NULL, NULL, NULL, 'in_person', NULL, NULL, ARRAY['enrollment through a school or accredited Duke of Ed Centre','Online Record Book (ORB) registration'], 'open_enrollment', 'open', 'Rolling / continuous enrollment via schools and Duke of Ed Centres -- no fixed annual application deadline', 'official_primary', 'https://dukeofed.com.au/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-04: Insight Creative Writing Competition -- cost='Free'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Insight Creative Writing Competition', 'insight creative writing competition', 'Insight Publications', 'competition', 'https://www.insightpublications.com.au/insight-creative-writing-competition/', 'https://www.insightpublications.com.au/insight-creative-writing-competition/', 'A free, national creative-writing competition for Australian high school students (Years 7-12), run by independent educational publisher Insight Publications. Entrants submit an original piece of creative writing (optional 2026 theme: ''IGNITE''); each year-level category is judged separately by an acclaimed Australian author. Prize pool exceeds AUD 3,000 across categories.', 'Australia', ARRAY['Australia'], true, NULL, NULL, ARRAY['7','8','9','10','11','12'], ARRAY['creative writing','english','literature'], 'Free', NULL, '2026-09-01', '2026-03-20', NULL, NULL, 'online', NULL, 'Open to high school students around Australia', ARRAY['original creative writing piece per entry-form guidelines','parent/guardian signature for entrants under 18'], 'competitive_award', 'open', '2026 competition currently open: entries opened 20 March 2026 and close 1 September 2026', 'official_primary', 'https://www.insightpublications.com.au/insight-creative-writing-competition/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-07: NYU Shanghai AI Pre-College Summer Program -- cost="CNY 26,800 per person (covers instruction, meals, and materials; housing and transportation are the participant's own responsibility)"
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('NYU Shanghai AI Pre-College Summer Program', 'nyu shanghai ai precollege summer program', 'NYU Shanghai', 'summer_program', 'https://shanghai.nyu.edu/academics/summer-academy/ai', 'https://shanghai.nyu.edu/academics/summer-academy/ai', 'A two-week, in-person, English-language pre-college summer program at NYU Shanghai''s campus for high school students aged 15-18 interested in artificial intelligence. Taught by NYU Shanghai faculty from the Computer Science, Data Science, and Engineering Division alongside the NYU Shanghai Center for Data Science, students build mathematical foundations for AI, gain hands-on experience with Python/NumPy/PyTorch, and study machine learning from linear regression through neural networks and AI agents.', 'China', '{}', false, 15, 18, '{}', ARRAY['artificial intelligence','computer science','data science'], 'CNY 26,800 per person (covers instruction, meals, and materials; housing and transportation are the participant''s own responsibility)', NULL, '2026-04-30', NULL, '2026-07-13', '2026-07-24', 'in_person', NULL, NULL, ARRAY['high school transcript (school-sealed)','English proficiency score (TOEFL/IELTS/Duolingo) if available','interview as part of admissions review'], 'selective', 'closed', '2026 cycle fully concluded -- program ran 13-24 July 2026 with application rounds that closed 15 March and 30 April 2026; 2027 dates not yet published', 'official_primary', 'https://shanghai.nyu.edu/academics/summer-academy/ai', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-EASIA-ANZ-11: National Olympiad in AI (NOAI) -- cost='Free for eligible MOE students'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('National Olympiad in AI (NOAI)', 'national olympiad in ai noai', 'AI Singapore', 'competition', 'https://aisingapore.org/talent/national-olympiad-in-artificial-intelligence/', 'https://noai.aisingapore.org/', 'Singapore''s national artificial-intelligence olympiad and official selection pathway to the International Olympiad in AI (IOAI). Run by AI Singapore (a national AI programme supported by Singapore''s National Research Foundation and hosted at the National University of Singapore), NOAI covers Machine Learning, Natural Language Processing, Computer Vision, and programming. A 300-question preliminary MCQ round narrows the field to the top 150 finalists, who sit a Final Assessment at Nanyang Technological University; a further ~50-60 of the strongest performers are selected for NTU-based training toward possible IOAI team representation.', 'Singapore', ARRAY['Singapore'], false, NULL, 20, '{}', ARRAY['artificial intelligence','computer science','machine learning'], 'Free for eligible MOE students', NULL, '2025-11-28', '2025-09-15', NULL, '2026-03-06', 'hybrid', 'Open to full-time students under age 20 currently enrolled at a Singapore MOE school (Secondary, Integrated Programme, Junior College, ITE, or Polytechnic) regardless of nationality; home-schooled Singapore Citizens/Permanent Residents are also eligible. A foreign national not enrolled at a Singapore school -- and conversely a Singapore citizen studying abroad -- would not qualify.', 'Must be enrolled at a Singapore MOE school (or home-schooled SC/PR)', ARRAY['school-based registration/interest declaration','300-question preliminary MCQ assessment'], 'highly_selective', 'closed', 'NOAI 2026 cycle fully concluded -- school interest window ran 15 Sept-28 Nov 2025 and the Final Assessment was held 6 March 2026 at NTU; NOAI 2027 registration not yet announced as of 2026-08-21', 'official_primary', 'https://aisingapore.org/talent/national-olympiad-in-artificial-intelligence/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-01: Shad Canada -- cost='CAD $7,495 (live-in/A+/Unplugged, domestic); CAD $3,955 (virtual, domestic); CAD $11,950 (live-in, international); CAD $6,715 (virtual, international) — 2026 cycle figures'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Shad Canada', 'shad canada', 'Shad Canada', 'summer_program', 'https://www.shad.ca/', 'https://www.shad.ca/apply/', 'A month-long STEAM and entrepreneurship summer program for Canadian high school students, delivered in partnership with 30+ Canadian post-secondary campuses. Students work in teams on open-ended design challenges alongside STEAM and entrepreneurship coursework. Live-in, commuter-style, and fully virtual tracks are all offered.', 'Canada', '{}', true, NULL, NULL, ARRAY['10','11'], ARRAY['STEAM','entrepreneurship','technology','engineering'], 'CAD $7,495 (live-in/A+/Unplugged, domestic); CAD $3,955 (virtual, domestic); CAD $11,950 (live-in, international); CAD $6,715 (virtual, international) — 2026 cycle figures', true, NULL, NULL, NULL, NULL, 'hybrid', NULL, NULL, '{}', 'selective', 'date_not_announced', '2026 cohort concluded (program ran Jul 5-31, 2026; application deadline was Jan 5, 2026). 2027 applications expected to open around September 2026 per Shad''s own stated pattern; exact 2027 dates not yet published as of this research.', 'official_primary', 'https://www.shad.ca/participate/', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-02: Euclid Contest -- cost='CAD $18.00 per participant, plus a $5.00 processing fee per order and shipping'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Euclid Contest', 'euclid contest', 'Centre for Education in Mathematics and Computing (CEMC), University of Waterloo', 'competition', 'https://cemc.uwaterloo.ca/contests/euclid', 'https://cemc.uwaterloo.ca/contests/euclid', 'A senior-level mathematics contest for students in their final year of secondary school (or CEGEP), featuring 10 questions mixing final-answer-only and full-solution formats over 2.5 hours. Strong results can support admission and scholarship consideration for the University of Waterloo''s Faculty of Mathematics.', 'Canada', '{}', false, NULL, NULL, ARRAY['12'], ARRAY['mathematics'], 'CAD $18.00 per participant, plus a $5.00 processing fee per order and shipping', NULL, '2027-03-11', NULL, '2027-04-06', '2027-04-07', 'in_person', NULL, NULL, ARRAY['school registration via a contest supervisor'], 'open_enrollment', 'upcoming', '2027 sitting (next scheduled edition as of Aug 2026): North/South America Apr 6, 2027; elsewhere Apr 7, 2027', 'official_primary', 'https://cemc.uwaterloo.ca/contests/euclid', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-03: Pascal, Cayley and Fermat Contests (PCF) -- cost='CAD $6.00 per participant, plus a $5.00 processing fee per order and shipping'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Pascal, Cayley and Fermat Contests (PCF)', 'pascal cayley and fermat contests pcf', 'Centre for Education in Mathematics and Computing (CEMC), University of Waterloo', 'competition', 'https://cemc.uwaterloo.ca/contests/pcf', 'https://cemc.uwaterloo.ca/contests/pcf', 'Three linked multiple-choice mathematics contests administered on the same contest day, differentiated by target grade level: Pascal (Grade 9 and below), Cayley (Grade 10 and below), and Fermat (Grade 11 and below). 25 questions, 60 minutes, scored out of 150; available on paper or online per school choice.', 'Canada', '{}', false, NULL, NULL, ARRAY['9','10','11'], ARRAY['mathematics'], 'CAD $6.00 per participant, plus a $5.00 processing fee per order and shipping', NULL, '2027-02-09', NULL, '2027-02-23', '2027-02-25', 'in_person', NULL, NULL, ARRAY['school registration via a contest supervisor'], 'open_enrollment', 'upcoming', '2027 sitting (next scheduled edition as of Aug 2026): North/South America Feb 23-24, 2027; elsewhere Feb 24-25, 2027', 'official_primary', 'https://cemc.uwaterloo.ca/contests/pcf', 'high', 'active', 'verified_current', '2026-08-21');
-- NIGHT1-CAN-TR-EU-04: Canadian Computing Competition (CCC) -- cost='CAD $10.00 per participant, plus a $5.00 processing fee per order (tax-exempt within Canada and internationally)'
-- INSERT INTO opportunities (title, normalized_title, organization, category, official_url, application_url, description, country, eligible_countries, remote_allowed, minimum_age, maximum_age, eligible_grades, fields, cost, financial_aid_available, deadline, application_open_date, start_date, end_date, location_mode, citizenship_restrictions, residency_restrictions, application_requirements, selectivity_tier, cycle_status, current_cycle_label, source, source_url, source_confidence, status, verification_state, verified_at) VALUES ('Canadian Computing Competition (CCC)', 'canadian computing competition ccc', 'Centre for Education in Mathematics and Computing (CEMC), University of Waterloo', 'competition', 'https://cemc.uwaterloo.ca/contests/ccc', 'https://cemc.uwaterloo.ca/contests/ccc', 'An annual programming contest for secondary school students with an interest in computer science, offered at Junior (beginner-intermediate) and Senior (intermediate-advanced) levels regardless of grade. 5 questions, 3 hours, written in school under supervision using an online grader (C, C++, Python 2/3, or Java). Top Senior performers may be invited to the Canadian Computing Olympiad (CCO).', 'Canada', '{}', false, NULL, NULL, ARRAY['9','10','11','12'], ARRAY['computer science','programming'], 'CAD $10.00 per participant, plus a $5.00 processing fee per order (tax-exempt within Canada and internationally)', NULL, '2027-02-11', NULL, '2027-02-17', '2027-02-18', 'in_person', NULL, NULL, ARRAY['school registration via a contest supervisor','CCC Online Grader account'], 'open_enrollment', 'upcoming', '2027 sitting (next scheduled edition as of Aug 2026): North/South America Feb 17, 2027; elsewhere Feb 18, 2027', 'official_primary', 'https://cemc.uwaterloo.ca/contests/ccc', 'high', 'active', 'verified_current', '2026-08-21');
